import React, { useState } from "react";
import styles from "./Explore.module.css";

const REGIONS = [
  "대산읍","지곡면","팔봉면","성연면","음암면","운산면","부춘동",
  "동문1동","동문2동","수석동","인지면","석남동","부석면","고북면"
];

const TABS = ["뉴스","복지","문화소식","서산시청","카페","블로그"];

const MOCK = Array.from({ length: 6 }).map((_, i) => ({
  id: i + 1,
  title: i === 1 ? "제목" : "아동 청소년을 위한 청소년 수련관 운영",
  body:
    i === 1
      ? "2줄"
      : "청소년활동진흥법의 규정에 따라 청소년활동을 적극적으로 진흥하기 위해 다양한 수련거리를 실시할 수 있도록 청소년수련관을 운영하고자 ○○에 위치한 …",
}));

export default function Explore() {
  const [activeRegion, setActiveRegion] = useState("대산읍");
  const [activeTab, setActiveTab] = useState("뉴스");

  return (
    <div className={styles.page}>
      <div className={styles.frame}>
        {/* 왼쪽 사이드바 */}
        <aside className={styles.side}>
          <div className={styles.sideTitle}>지역</div>
          <ul className={styles.sideList}>
            {REGIONS.map((r) => (
              <li
                key={r}
                className={`${styles.sideItem} ${
                  r === activeRegion ? styles.sideItemActive : ""
                }`}
                onClick={() => setActiveRegion(r)}
              >
                {r}
              </li>
            ))}
          </ul>
        </aside>

        {/* 오른쪽 컨텐츠 */}
        <main className={styles.main}>
          {/* 상단 탭 (하얀 알약 박스) */}
          <div className={styles.tabPill}>
            {TABS.map((t) => (
              <button
                key={t}
                type="button"
                className={`${styles.tabBtn} ${
                  t === activeTab ? styles.tabBtnActive : ""
                }`}
                onClick={() => setActiveTab(t)}
              >
                {t}
              </button>
            ))}
          </div>

          {/* 결과 카운트 바 */}
          <div className={styles.countBar}>글 전체 결과 3,435개</div>

          {/* 리스트 */}
          <section className={styles.list}>
            {MOCK.map((item) => (
              <article key={item.id} className={styles.card}>
                <h3 className={styles.cardTitle}>{item.title}</h3>
                <div className={styles.divider} />
                <p className={styles.cardBody}>{item.body}</p>
                <div className={styles.cardFooter}>
                  <a className={styles.viewLink} href="#!">
                    보기
                  </a>
                  <span className={styles.circleIcon} aria-hidden />
                </div>
              </article>
            ))}
          </section>
        </main>
      </div>
    </div>
  );
}
